function e(e,t){let n=Math.abs(Math.trunc(e)),r=Math.abs(Math.trunc(t));for(;r!==0;)[n,r]=[r,n%r];return n}function t(e,t){let n=[],r=Math.abs(Math.trunc(e)),i=Math.abs(Math.trunc(t));if(i===0)return n;for(;i!==0;){let e=Math.floor(r/i),t=r%i;n.push({a:r,b:i,quotient:e,remainder:t}),r=i,i=t}return n}function n(e){let t=Math.max(Math.abs(Math.trunc(e)),1),n=[];for(let e=1;e<=t;e++)t%e===0&&n.push(e);return n}export{e as n,t as r,n as t};